<?php require_once __DIR__ . '/auth.php'; require_login('student');$leaders=many('SELECT u.name,COALESCE(SUM(qa.score),0) points,COALESCE(SUM(qa.questions_count),0) solved,COALESCE(ROUND(AVG(qa.accuracy)),0) accuracy FROM users u LEFT JOIN quiz_attempts qa ON qa.user_id=u.id WHERE u.role=\'student\' GROUP BY u.id ORDER BY points DESC,accuracy DESC');$pageTitle='Leaderboard';include 'includes/header.php';?><div class="page-head"><div><div class="eyebrow">The weekly signal</div><h1>Leaderboard.</h1><p>Points reward correct answers, challenge level, and steady improvement.</p></div><span class="pill lime">This week</span></div><div class="rank-list"><?php foreach($leaders as $index=>$leader):?><div class="rank-item"><div class="rank-number">#<?=($index+1)?></div><div class="rank-meta"><strong><?=e($leader['name'])?></strong><small><?=$leader['accuracy']?>% accuracy · <?=$leader['solved']?> questions solved</small></div><span class="pill">Technical track</span><div class="rank-points"><?=number_format($leader['points'])?> pts</div></div><?php endforeach;?></div><?php include 'includes/footer.php';?>